UMaterial* Resolve(const FRenderTargetReq& R) {
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || R.AssetPath.IsEmpty() || R.AssetPath.Len()>2048) throw std::runtime_error("Stopped editor/bounded loaded material path required");
 auto* M=FindObject<UMaterial>(nullptr,*R.AssetPath); if(!IsValid(M) || M->GetClass()!=UMaterial::StaticClass() || !M->IsAsset() || M->IsTemplate() || M->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || M->GetPathName()!=R.AssetPath || !M->GetEditorOnlyData()) throw std::runtime_error("Exact loaded native material/editor data required"); return M;
}
FString Snapshot(const UMaterial* M) {
 FString Json; auto J=TJsonWriterFactory<>::Create(&Json); J->WriteArrayStart(); for(const auto& G:M->GetEditorOnlyData()->ParameterGroupData) { J->WriteObjectStart(); J->WriteValue(TEXT("name"),G.GroupName); J->WriteValue(TEXT("priority"),G.GroupSortPriority); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->Close(); return Json;
}
