 if(Changed && !R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Set Material Parameter Group Priority"))); M->SetFlags(RF_Transactional); Data->SetFlags(RF_Transactional); M->Modify(); Data->Modify(); Groups[R.Start].GroupSortPriority=Requested; if(M->GetEditorOnlyData()!=Data || Groups!=Expected) throw std::runtime_error("Material group metadata readback failed"); M->MarkPackageDirty(); }
