UObject* ResolveMetadataOwner(const FRenderTargetReq& R) {
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || R.AssetPath.IsEmpty() || R.AssetPath.Len()>2048) throw std::runtime_error("Stopped editor/bounded loaded material or function path required");
 auto* Owner=FindObject<UObject>(nullptr,*R.AssetPath); if(!IsValid(Owner) || !Owner->IsAsset() || Owner->IsTemplate() || Owner->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || Owner->GetPathName()!=R.AssetPath || (Owner->GetClass()!=UMaterial::StaticClass() && Owner->GetClass()!=UMaterialFunction::StaticClass())) throw std::runtime_error("Exact loaded nativeMaterial or MaterialFunction required"); return Owner;
}
TArray<UMaterialExpression*> OwnerExpressions(UObject* Owner) {
 TArray<UMaterialExpression*> Result; if(auto* M=Cast<UMaterial>(Owner)) { for(UMaterialExpression* E:M->GetExpressions()) Result.Add(E); } else if(auto* F=Cast<UMaterialFunction>(Owner)) { for(UMaterialExpression* E:F->GetExpressions()) Result.Add(E); } return Result;
}
bool ExpressionOwnedBy(const UMaterialExpression* E,const UObject* Owner) { return E->GetTypedOuter<UMaterial>()==Owner || E->GetTypedOuter<UMaterialFunction>()==Owner; }
UMaterialExpression* ResolveExpression(UObject* M,const FRenderTargetReq& R) {
 if(R.ExpressionPath.IsEmpty() || R.ExpressionPath.Len()>2048) throw std::runtime_error("Bounded expression path required"); auto* E=FindObject<UMaterialExpression>(nullptr,*R.ExpressionPath); FGuid Guid;
 if(!IsValid(E) || E->IsTemplate() || E->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || E->GetPathName()!=R.ExpressionPath || !ExpressionOwnedBy(E,M) || !FGuid::Parse(R.ExpressionGuid,Guid) || !Guid.IsValid() || E->MaterialExpressionGuid!=Guid) throw std::runtime_error("Exact material/function-owned expression path/node GUID required");
 bool Found=false; for(UMaterialExpression* Item:OwnerExpressions(M)) if(Item==E) Found=true; if(!Found) throw std::runtime_error("Expression must belong to current material/function collection"); return E;
}
FString ExpressionMetadata(const UMaterialExpression* E) {
 FString Json; auto J=TJsonWriterFactory<>::Create(&Json); J->WriteObjectStart(); J->WriteValue(TEXT("class_path"),E->GetClass()->GetPathName()); J->WriteValue(TEXT("node_guid"),E->MaterialExpressionGuid.ToString());
 for(const TCHAR* Name:{TEXT("ParameterName"),TEXT("Collection"),TEXT("ParameterId"),TEXT("DefaultValue"),TEXT("Font"),TEXT("FontTexturePage"),TEXT("DefaultR"),TEXT("DefaultG"),TEXT("DefaultB"),TEXT("DefaultA"),TEXT("DynamicBranch"),TEXT("Input"),TEXT("A"),TEXT("B"),TEXT("ExpressionGUID"),TEXT("Group"),TEXT("SortPriority"),TEXT("Desc"),TEXT("SliderMin"),TEXT("SliderMax"),TEXT("ControlType"),TEXT("Enumeration"),TEXT("EnumerationIndex"),TEXT("ChannelNames"),TEXT("Texture"),TEXT("SamplerType"),TEXT("SamplerSource"),TEXT("MipValueMode"),TEXT("ConstCoordinate"),TEXT("ConstMipValue"),TEXT("GatherMode"),TEXT("AutomaticViewMipBias"),TEXT("Coordinates"),TEXT("TextureObject"),TEXT("MipValue"),TEXT("CoordinatesDX"),TEXT("CoordinatesDY"),TEXT("AutomaticViewMipBiasValue"),TEXT("bUseCustomPrimitiveData"),TEXT("PrimitiveDataIndex")}) { const auto* P=FindFProperty<FProperty>(E->GetClass(),Name); if(!P) continue; FString Value; P->ExportTextItem_Direct(Value,P->ContainerPtrToValuePtr<void>(E),nullptr,const_cast<UMaterialExpression*>(E),PPF_None); J->WriteValue(Name,Value); } J->WriteObjectEnd(); J->Close(); return Json;
}
