  if(!GEditor->Trans || !R.bConfirm || E->GetClass()->GetPathName()!=R.ExpectedClassPath || R.ExpectedAssetSnapshot.IsEmpty() || R.ExpectedAssetSnapshot.Len()>65536 || ExpressionMetadata(E)!=R.ExpectedAssetSnapshot || R.Color.Num()!=2 || R.ExpectedColor.Num()!=2 || !E->CanEditChange(MinP) || !E->CanEditChange(MaxP)) throw std::runtime_error("Confirmed scalar class/full metadata snapshot/native slider editability/full prior-requested min-max required");
